// MARK: - OptionSwatchControl

/// The shared color panel keeps a bare target reference, so the panel aims
/// at this stable relay and the relay holds the most recently clicked swatch
/// weakly — a rebuilt bar can never leave the panel pointing at a freed
/// control, and only one swatch is bound at a time.
private final class SwatchColorRelay: NSObject {
    static let shared = SwatchColorRelay()
    weak var swatch: OptionSwatchControl?

    @objc func colorChanged(_ sender: Any?) {
        swatch?.colorPanelDidPick(NSColorPanel.shared.color)
    }
}

/// 22×22 color swatch over a tiny checkerboard so alpha reads; clicking
/// binds the shared NSColorPanel to this swatch's descriptor closures.
final class OptionSwatchControl: NSView, OptionControl {
    private let read: () -> NSColor
    private let write: (NSColor) -> Void
    private let enabled: () -> Bool
    /// order and every delegate that can cancel a termination inherits it;
    /// nothing is lost, and asking first is not on offer.
    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        // ⌘Q with a recording running (road map 3, R1c): cancel, stop nothing,
        // and put the recording's controls in front of the person — who, if
        // they meant to stop, presses Stop. A quit that silently finished the
        // recording would land a file into a document that is about to ask
        // whether to save, the wrong moment for both. This is a BACKSTOP
        // asked after the document review above; `RecorderPanelController`'s
        // doc records what that order means for the recording's target. The
        // panel is HIDDEN for every recording it runs (decision 7), so
        // `revealControls()` opens the status item's menu — Pause or Resume,
        // and Stop — where `show()` could only beep (R2 review: a person who
        // paused and forgot was beeped at); for a recording the panel does
        // not own (the tool's) it shows the panel as before.
        if ScreenRecorder.shared.isRecording {
            RecorderPanelController.shared.revealControls()
            return .terminateCancel
        }
        let queue = ExportQueueController.shared
        guard !queue.isIdle else { return .terminateNow }

        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = "An export is still being written."
        let running = queue.runningJob.map { "“\($0.name)”" } ?? "An export"
        let waiting = queue.waitingCount
        alert.informativeText =
            "\(running) is not finished"
            + (waiting > 0 ? ", and \(waiting) more \(waiting == 1 ? "is" : "are") waiting" : "")
            + ". Quitting now stops it and deletes the partly written file."
        alert.addButton(withTitle: "Quit Anyway")
        alert.addButton(withTitle: "Cancel")
        guard alert.runModal() == .alertFirstButtonReturn else { return .terminateCancel }

        queue.cancelAll()
        var sentences: [String] = []
        if let microphoneProblem {
            sentences.append(
                "The microphone stopped: \(microphoneProblem) The picture is still recording.")
        }
        if let resumeProblem { sentences.append(resumeProblem) }
        return sentences.joined(separator: " ")
    }

    // MARK: - The hidden recording's one door

    /// The quit guard's call (`AppDelegate.applicationShouldTerminate`).
    /// While this panel is hidden for its recording `show()` can only beep,
    /// and a beep tells a person who paused and forgot nothing — so the
    /// status item's menu is opened instead, Pause or Resume and Stop put
    /// in front of them (`RecorderStatusItem.openMenu`); the beep is kept
    /// for the one case with no item to open. Any other recording — a
    /// tool's, which File ▸ Stop Recording ends — shows the panel as before.
    func revealControls() {
        guard hiddenForRecording else {
            show()
            return
        }
        if statusItem?.openMenu() != true { NSSound.beep() }
    }

    // MARK: - The phases, drawn

    /// Draws the phase: the button's title and enabled state, the controls
    /// locked while anything is in flight, the countdown numeral, the
    /// footnote, the camera preview (CAM-7), and the window refitted to
        setNote(error.localizedDescription)
    }

    /// The recording chrome (decision 7): the status item in the menu bar
    /// with Pause, Resume and Stop (`+Pause.swift` for the first two), the
    /// 30 Hz tick, and the panel ordered OUT for EVERY source until the
    /// landing has something to say — whether or not it was on screen
    /// (`show()` beeps meanwhile; `showWhenLanded` remembers, and
    /// `revealIfNoted` reads it). R1 hid it for a picked window only,
    /// because a display's filter excludes Frame Job (R0 q3); the user asked
    /// for the dialog to go away whatever is recorded, and the menu bar's
    /// item is the recording's controls now. A voice-over and a camera are
    /// the exceptions (`hidesForRecording`): the panel stays as it was, so it is never
    /// `hiddenForRecording` and `showWhenLanded` is simply whether it is up.
    func recordingDidStart() {
        // A stop asked for while arming has moved the phase on; the end
        // comes through `recordingEnded`.
        guard phase == .starting else { return }
        phase = .recording
        resumeProblem = nil
        setNote("")
        let item = RecorderStatusItem(
            keys: recorder.recordsKeys,
            onPause: { [weak self] in self?.pauseRecording() },
            onResume: { [weak self] in self?.resumeRecording() },
            onStop: { [weak self] in self?.stopRecording() })
        item.show()
        statusItem = item
        armTick()
        showWhenLanded = window?.isVisible == true
        guard Self.hidesForRecording(currentChoice().source) else { return }
        hiddenForRecording = true
        window?.orderOut(nil)
    }

    // MARK: - The tick

    /// 30 Hz from the countdown's start, in `.common` modes (the type doc).
    /// Through `.countdown` and `.starting` it ONLY meters — the prepared
    /// session's level (#98 c; the recorder publishes nothing while
    /// arming, so the bar holds its last pre-roll level for that instant).
    /// While recording or paused: the microphone's level into the panel's
    /// own meter (`ScreenRecorder.publishMicrophoneLevel`, a no-op without
    /// a microphone and while paused, the recorder having silenced the
    /// bar), the elapsed time in the footnote and in the status item — with
    /// `paused`, which is what flips the item's menu — and a microphone
    /// problem into the note. `recordingDidStart` re-arms it.
    private func armTick() {
        tickTimer?.invalidate()
        let timer = Timer(timeInterval: 1.0 / 30, repeats: true) { [weak self] timer in
            guard let self else {
                timer.invalidate()
                return
            }
            switch self.phase {
            case .countdown, .starting:
                self.recorder.publishMicrophoneLevel()
                return
            default:
                break
            }
            guard self.phase == .recording || self.phase == .paused || self.phase == .stopping
            else {
                timer.invalidate()
                return
            }
/// filter excluding Frame Job (R0 q3), and hid only a PICKED window's; the
/// user asked for the dialog to go away whatever is recorded, and a panel
/// whose one live control was a Stop the menu bar also has earned nothing
/// on screen. It comes back after the landing ONLY when it was on screen
/// as the recording began (`showWhenLanded`, read at `recordingDidStart`)
/// AND the landing left a note (`revealIfNoted`, `+Landing.swift`): a stop
/// from the system's own indicator, a closed target, a microphone problem,
/// a refused resume, a failure. A clean recording lands and the panel
/// stays away, and a panel closed before the recording began stays closed
/// whatever the note; ⌥⌘N shows it again. `show()` BEEPS while
/// `hiddenForRecording` (R1 review) — the welcome window's button reaches
/// it — because a panel un-hidden into the recording would be in the file;
/// the quit guard goes through `revealControls()` instead (`+Pause.swift`).
/// **It takes key only from an active Frame Job** (spec §11, #137): shown from
/// the background it is ordered front without key, so Return stays with
/// the app in front. **A voice-over stays UP** (#99): nothing is filmed, so
/// the rows lock, the meter stays live, Record reads Stop with a Pause /
/// Resume button beside it; Close takes the panel away and the recording
/// carries on — the welcome button and the quit guard show the panel again,
/// and ⌥⌘N (File ▸ Stop Recording) and the status item stop it. **So does
/// a camera recording** (CAM-5), on the same terms: nothing on screen is
/// filmed.
///
/// Two limits of that chrome, accepted (R2 review). With the panel hidden
/// the status item is the ONLY Pause and Resume, and macOS drops a status
/// item that does not fit the menu bar — behind a notch, in a crowded bar
/// — so there Stop survives in the File menu and Pause and Resume do not.
/// And "●" and "❚❚" differ in width under `variableLength`, so the items to
/// the left of it shift by a few points at each pause and resume.
///
/// **Quit while recording, and the order AppKit asks in.**
/// `AppDelegate.applicationShouldTerminate` cancels a quit while
/// `ScreenRecorder.shared.isRecording` and calls `revealControls()` — the
/// status item's menu, opened, while this panel is hidden for its
/// recording; `show()` for any other (a tool's, which File ▸ Stop Recording
/// ends) — and it is a BACKSTOP: `NSDocumentController` reviews modified
/// documents FIRST, so the save sheet comes before the guard, and a target
/// document the review CLOSED lands as `.newProject` —
/// `RecordingLanding.resolve` looks the destination up by `recipeKey`,
/// never minted twice, so the miss is exact, and the landing's note says
/// the document was closed.
    /// Overwrite at Playhead cannot place a row nobody can see (#68). No work
    /// when nothing selected is hidden: `arrange()` calls it on every refresh.
    func dropHiddenSelection() {
        guard let document = binding.document, let media = document.selectedMedia,
              let row = rows.first(where: { $0.media == media }), row.view.isHidden
        else { return }
        document.selectedMedia = nil
        row.view.needsDisplay = true
    }

    /// The row menu's Insert / Overwrite at Playhead. The same two ops the
    /// Edit menu runs, on the row that was right-clicked.
    func place(_ media: UInt32, insert: Bool) {
        select(media)
        guard binding.snapshot.media(media) != nil,
              let track = binding.document?.targetTrack
        else {
            NSSound.beep()
            return
        }
        let at = ReelTime.snapToFrame(max(binding.playhead, 0), fps: binding.canvas.fps)
        binding.apply(
            insert ? "Insert" : "Overwrite",
            [
                insert
                    ? .insertClip(track: track, media: media, at: at)
                    : .overwriteClip(track: track, media: media, at: at)
            ])
    }

    /// Whether the row menu's Reveal in Timeline has anything to reveal —
    /// asked by the row as it builds the menu, so the item is dead rather
    /// than silently doing nothing.
    ///
    /// It is `timelineClipsUsing` and not `clipsUsing` deliberately: media
    /// used only INSIDE a nest has users the selection cannot hold
    /// (`MediaUsage.swift`), and this is the case the pane's old
    /// top-level-only usage test could not tell apart from "used by nothing".
    func canRevealInTimeline(_ media: UInt32) -> Bool {
        !binding.snapshot.timelineClipsUsing(media).isEmpty
    }

    /// The row menu's Reveal in Timeline: select every top-level clip that
    /// shows this file, and scroll the first one into view.
    ///
    /// The selection is VIEW state, so this writes it on the document the way
    /// `select(_:)` writes `selectedMedia` — no op, no undo step — and then
    /// asks the editor to publish it, because the notification and the scroll
    /// both belong to the editor (`MediaReveal.swift`).
    ///
    /// **It throws the panel off this tab, and that is accepted rather than
    /// fought.** `InspectorViewController.refresh(isLive:)` switches to the
    /// Clip tab whenever a non-empty selection changes, which is the panel's
    /// rule for ⌘A, paste and the agent's `set_selection` alike; a command
    /// whose whole point is "here are the clips" has no business being the
    /// one exception, and the Media tab is one click away.
    func revealInTimeline(_ media: UInt32) {
        select(media)
        let clips = binding.snapshot.timelineClipsUsing(media)
        guard !clips.isEmpty, let document = binding.document else {
            NSSound.beep()
            return
        }
        document.selection = Set(clips.map { $0.id })
        inspector?.onCommand?(#selector(EditorViewController.revealSelectionInTimeline(_:)))
    }

    /// The row menu's Reveal in Finder: a copy's original, else the file.
    func reveal(_ media: UInt32) {
        guard let entry = binding.snapshot.media(media), let url = revealURL(for: entry) else {
            NSSound.beep()
            return
        }
        NSWorkspace.shared.activateFileViewerSelecting([url])
    }

    /// Relink… — the offer a project whose media has moved opens with (§5.6).
    ///
    /// **One of three relink paths, and all three probe the new file and
    /// owe the cache pass** (spec §11, #63). The chosen file goes to
    /// `ProjectDocument.relinkMedia`, the body this path shares with the
    /// missing-media sheet: import's own probe, so the entry takes the file's
    /// duration, size, rate and flags, a file of another kind is refused in
    /// the core's sentence and a clip past a shorter file's end is held to
    /// it; one grouped undo step; then `ProjectDocument.generateCaches`, the
    /// app's one spelling of "make what is missing", because a relinked file
    /// may be one this project has never read — no filmstrip, thumbnail or
    /// peaks on disk — and nothing downstream of an edit makes them. The
    /// agent's `relink_media` (`AgentServer.relinkMedia`) probes and passes
    /// the same way. What the pass costs is its own doc's: a stat, a marker
    /// read per half and a `fileExists` per media whose marker still matches,
    /// and a rebuild for the one whose file just changed.
    func relink(_ media: UInt32) {
        guard let entry = binding.snapshot.media(media), let window = window else {
            NSSound.beep()
            return
        }
        let binding = self.binding
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.message = "Choose the file for “\(entry.name)”."
        panel.beginSheetModal(for: window) { response in
            guard response == .OK, let url = panel.url else { return }
            binding.document?.relinkMedia([(media: media, url: url)])
        }
    }

    /// Remove — refused while the media is in use, with the "and its clips"
    /// offer §4.3 asks for.
    ///
    /// The users are counted through `clipsUsing`, which walks the NESTS as
    /// well as the timeline, because that is the set `remove_media` refuses
    /// against and the set `with_clips: true` deletes. Filtering
    /// `snapshot.clips` here — what this line used to do — meant that media
    /// used only inside a compound clip looked unused, went to the core as a
    /// plain `remove_media`, came back refused, and reached the user as a
    /// beep with the alert never shown (`MediaUsage.swift`).
    func remove(_ media: UInt32) {
        guard let entry = binding.snapshot.media(media) else {
            NSSound.beep()
            return
        }
        // The DOCUMENT's clips, never the scoped view's: `remove_media` is a
        // document-level op (`ReelOp.isDocumentLevel`) and is sent unscoped
        // even with a nest open, so the "and its clips" count has to be the
        // whole file's — the timeline's clips chained with every nest's —
        // or the alert would under-count and the op would refuse.
        let users = binding.documentSnapshot.clipsUsing(media)
        // A LUT that is a media's Camera Log (spec §11 GR-16) is used too:
        // `with_clips` clears those conversions with the looks.
        let converted = entry.kind == .lut
            ? binding.documentSnapshot.mediaConverted(by: media).count : 0
        guard !users.isEmpty || converted > 0 else {
            binding.apply("Remove Media", [.removeMedia(media: media)])
            return
        }
        guard let window = window else {
            NSSound.beep()
            return
        }
        let binding = self.binding
        let alert = NSAlert()
        alert.messageText = "Remove “\(entry.name)”?"
        // A LUT's users keep their place and lose the look (spec §11 GR-8),
        // and the files it converts lose their Camera Log (GR-16).
        if entry.kind == .lut {
            var parts: [String] = []
            if !users.isEmpty {
                parts.append(
                    users.count == 1
                        ? "It is the look of 1 clip, which keeps its place and loses the look."
                        : "It is the look of \(users.count) clips, which keep their place and "
                            + "lose the look.")
            }
            if converted > 0 {
                parts.append(
                    (users.isEmpty ? "It is" : "…and")
                        + " the Camera Log of \(converted) file\(converted == 1 ? "" : "s"), "
                        + "which lose\(converted == 1 ? "s" : "") it.")
            }
            alert.informativeText = parts.joined(separator: " ")
        } else {
            alert.informativeText =
                users.count == 1
                ? "It is used by 1 clip, which will be removed with it."
                : "It is used by \(users.count) clips, which will be removed with it."
        }
        alert.addButton(
            withTitle: entry.kind == .lut ? "Remove and Clear Looks" : "Remove and Delete Clips")
        alert.addButton(withTitle: "Cancel")
        alert.beginSheetModal(for: window) { response in
            guard response == .alertFirstButtonReturn else { return }
            binding.applyGrouped(
                "Remove Media", [.removeMedia(media: media, withClips: true)])
        }
    }
}
        }
    }
    return URL(fileURLWithPath: cursor.path)
}

/// What Reveal in Finder shows: the original, or the copy when the original
/// is gone (spec §11 #228-O, O11).
func revealURL(for media: MediaSnapshot) -> URL? {
    originalURL(for: media) ?? mediaURL(for: media)
}

/// Whether `url` lies inside `folder` — strictly: `folder` itself is not
/// inside itself. Pure path arithmetic on the standardized paths.
func isInside(_ url: URL, folder: URL) -> Bool {
    let base = folder.standardizedFileURL.path
    return url.standardizedFileURL.path.hasPrefix(base.hasSuffix("/") ? base : base + "/")
}

