/// Settings' MCP pane (issue batch B74, spec §11 MC-7): the first of
/// `SettingsWindowController`'s panes. It says how an MCP client reaches
/// Frame Job — through the bundled `framejob-mcp` (MC-1, MC-3), which opens
/// Frame Job in the background on the first tool call (MC-4) — shows that
/// helper's path, and holds Copy MCP Command, which puts MC-3's line on the
/// pasteboard.
///
/// **The blurb is visible, not behind an ⓘ** (MC-7): the owner asked for it
/// above the button, so the heading has no `SettingsInfoButton`.
///
/// **One spelling of the path and the line.** The helper's URL arrives from
/// `AgentServer.mcpHelperURL` through `SettingsWindowController`'s defaulted
/// parameter, and the line is `AgentServer.mcpCommand(helperPath:)`; the pane
/// builds neither itself. The pasteboard is a parameter too, so a probe hands
/// it a private one and never writes the general pasteboard.
///
/// **The button is enabled exactly while the helper is executable.** A copy
/// of Frame Job without it says so in the status line. The press is not an
/// edit, so it has no MCP mirror (spec §7.9).
final class MCPSettingsPane: NSStackView {
    static let paneTitle = "MCP"
    static let blurb = [
        "An MCP client such as Claude Code uses Frame Job's tools through framejob-mcp, a helper "
            + "inside this app. It reaches Frame Job over a local socket that only programs you "
            + "run can open.",
        "If Frame Job isn't running, the first tool call opens it in the background. To add "
            + "Frame Job to Claude Code, copy the command and run it in Terminal.",
    ]
    static let copyTitle = "Copy MCP Command"
    static let copiedStatus = "Copied. Paste it into Terminal and press Return."
    static let missingStatus = "framejob-mcp is missing from this copy of Frame Job."
    /// The Settings window's width less its two insets.
    private static let textWidth: CGFloat = 420

    let helperURL: URL
    let pasteboard: NSPasteboard

    let headingLabel = NSTextField(labelWithString: MCPSettingsPane.paneTitle)
    let blurbLabels: [NSTextField] = MCPSettingsPane.blurb.map {
        NSTextField(wrappingLabelWithString: $0)
    }
    let helperLabel = NSTextField(wrappingLabelWithString: "")
    let statusLabel = NSTextField(wrappingLabelWithString: "")
    private(set) var copyButton: NSButton!

    /// MC-3's line for this pane's helper.
    var command: String { AgentServer.mcpCommand(helperPath: helperURL.path) }

    init(helperURL: URL, pasteboard: NSPasteboard) {
        self.helperURL = helperURL
        self.pasteboard = pasteboard
        super.init(frame: .zero)
        build()
        sync()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("MCPSettingsPane does not support NSCoder")
    }

    private func build() {
        headingLabel.font = DS.sans(15, weight: .bold)
        headingLabel.textColor = DS.textStrong
        headingLabel.setAccessibilityIdentifier("settings.mcp.heading")

        for (index, label) in blurbLabels.enumerated() {
            label.font = DS.sans(13)
            label.textColor = DS.textStrong
            label.preferredMaxLayoutWidth = Self.textWidth
            label.setAccessibilityIdentifier("settings.mcp.blurb.\(index + 1)")
        }

        helperLabel.stringValue = helperURL.path
        helperLabel.font = DS.mono(12)
        helperLabel.textColor = DS.textStrong
        helperLabel.isSelectable = true
        helperLabel.lineBreakMode = .byCharWrapping
        helperLabel.preferredMaxLayoutWidth = Self.textWidth
        helperLabel.setAccessibilityIdentifier("settings.mcp.helper")

        statusLabel.font = DS.sans(12)
        statusLabel.textColor = DS.textMuted
        statusLabel.preferredMaxLayoutWidth = Self.textWidth
        statusLabel.setAccessibilityIdentifier("settings.mcp.status")

        copyButton = StickerButton(
            title: Self.copyTitle, style: .secondary, target: self,
            action: #selector(copyClicked(_:)))
        copyButton.setAccessibilityIdentifier("settings.mcp.copy")

        orientation = .vertical
        alignment = .leading
        spacing = 12
        let views: [NSView] = [headingLabel] + blurbLabels + [helperLabel, copyButton, statusLabel]
        for view in views { addArrangedSubview(view) }
        for label in blurbLabels.dropLast() { setCustomSpacing(8, after: label) }
    }

    /// Whether the button can do anything, and the status that goes with it:
    /// empty while the helper is executable, `missingStatus` while it is not.
    func sync() {
        let present = FileManager.default.isExecutableFile(atPath: helperURL.path)
        copyButton.isEnabled = present
        statusLabel.stringValue = present ? "" : Self.missingStatus
    }

    /// Puts MC-3's line on the pane's pasteboard. A helper that went missing
    /// since the last sync writes nothing and shows why.
    @objc func copyClicked(_ sender: Any?) {
        guard FileManager.default.isExecutableFile(atPath: helperURL.path) else {
            sync()
            return
        }
        pasteboard.clearContents()
        pasteboard.setString(command, forType: .string)
        statusLabel.stringValue = Self.copiedStatus
    }
}
import AppKit

/// Settings' Playback pane (spec §11 G-38 (a)): Background render, on, and
/// the idle wait before it starts, under the Transcription pane in
/// `SettingsWindowController`'s one stack. Its heading carries a
/// `SettingsInfoButton` holding `explanation()` (SH-5).
///
/// One row, AssistantSettingsPane's compaction row's shape: the checkbox,
/// "Start after", the seconds field and its stepper, "seconds". The field and
/// the stepper are enabled only while the box is ticked. Each control saves
/// at once through `BackgroundRenderSettings.save`, with no Save button; a
/// field value outside `delayRange` beeps and shows the stored value again,
/// writing nothing. The pane holds no reference to `BackgroundRender`: a
/// click or a key in it is activity like any other, and every restart of
/// the idle clock reads the stored delay. It is a person's setting — no tool
/// reads or writes it (AI-11, R6-12).
final class PlaybackSettingsPane: NSStackView {
    static let paneTitle = "Playback"
    static let backgroundTitle = "Background render"
    static let delayText = "Start after"
    static let secondsText = "seconds"

    private let defaults: UserDefaults

    let headingLabel = NSTextField(labelWithString: PlaybackSettingsPane.paneTitle)
    /// The heading's ⓘ, holding `explanation()` (SH-5).
    let infoButton = SettingsInfoButton(
        section: PlaybackSettingsPane.paneTitle, infoText: PlaybackSettingsPane.explanation())
    let backgroundBox = NSButton(
        checkboxWithTitle: PlaybackSettingsPane.backgroundTitle, target: nil, action: nil)
    let delayField = NSTextField()
    let delayStepper = NSStepper()
    let secondsLabel = NSTextField(labelWithString: PlaybackSettingsPane.secondsText)

    init(defaults: UserDefaults) {
        self.defaults = defaults
        super.init(frame: .zero)
        build()
        sync()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("PlaybackSettingsPane does not support NSCoder")
    }

    private func build() {
        headingLabel.font = DS.sans(15, weight: .bold)
        headingLabel.textColor = DS.textStrong
        headingLabel.setAccessibilityIdentifier("settings.playback.heading")
        infoButton.setAccessibilityIdentifier("settings.playback.info")

        backgroundBox.font = DS.sans(13)
        backgroundBox.target = self
        backgroundBox.action = #selector(backgroundToggled(_:))
        backgroundBox.setAccessibilityIdentifier("settings.playback.background")

        let delayLabel = fieldLabel(Self.delayText)
        DSField.style(delayField)
        delayField.alignment = .right
        delayField.target = self
        delayField.action = #selector(delayChanged(_:))
        delayField.cell?.sendsActionOnEndEditing = true
        delayField.widthAnchor.constraint(equalToConstant: 44).isActive = true
        delayField.setAccessibilityIdentifier("settings.playback.delay")

        let range = BackgroundRenderSettings.delayRange
        delayStepper.minValue = Double(range.lowerBound)
        delayStepper.maxValue = Double(range.upperBound)
        delayStepper.increment = 1
        delayStepper.valueWraps = false
        delayStepper.autorepeat = true
        delayStepper.target = self
        delayStepper.action = #selector(delayStepped(_:))
        delayStepper.setAccessibilityIdentifier("settings.playback.stepper")

        secondsLabel.font = DS.sans(13)
        secondsLabel.textColor = DS.textMuted

        orientation = .vertical
        alignment = .leading
        spacing = 12
        let delayRow = NSStackView(
            views: [backgroundBox, delayLabel, delayField, delayStepper, secondsLabel])
        delayRow.orientation = .horizontal
        delayRow.alignment = .centerY
        delayRow.spacing = 6
        // Hugs at its content, so its width is not a tie with the column's (#143).
        delayRow.setHuggingPriority(.required, for: .horizontal)
        addArrangedSubview(settingsSectionHeader(headingLabel, info: infoButton))
        addArrangedSubview(delayRow)
    }

    // MARK: - Syncing

    /// The stored setting on the controls; the field and the stepper enabled
    /// only while the box is ticked, the field never written while it is
    /// being edited. Reads only, never writes.
    func sync() {
        let settings = BackgroundRenderSettings.load(from: defaults)
        backgroundBox.state = settings.enabled ? .on : .off
        delayField.isEnabled = settings.enabled
        delayStepper.isEnabled = settings.enabled
        delayStepper.integerValue = settings.delaySeconds
        if delayField.currentEditor() == nil {
            delayField.stringValue = String(settings.delaySeconds)
        }
    }

    // MARK: - Controls

    @objc func backgroundToggled(_ sender: Any?) {
        var settings = BackgroundRenderSettings.load(from: defaults)
        settings.enabled = backgroundBox.state == .on
        settings.save(to: defaults)
        sync()
    }

    /// The field's commit (Return or leaving it). Outside the range beeps and
    /// shows the stored value again, writing nothing.
    @objc func delayChanged(_ sender: Any?) {
        var settings = BackgroundRenderSettings.load(from: defaults)
        let typed = delayField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let seconds = Int(typed), BackgroundRenderSettings.delayRange.contains(seconds) else {
            NSSound.beep()
            delayField.stringValue = String(settings.delaySeconds)
            return
        }
        settings.delaySeconds = seconds
        settings.save(to: defaults)
        sync()
        delayField.stringValue = String(seconds)
    }

    @objc func delayStepped(_ sender: Any?) {
        var settings = BackgroundRenderSettings.load(from: defaults)
        settings.delaySeconds = delayStepper.integerValue
        settings.save(to: defaults)
        sync()
        delayField.stringValue = String(settings.delaySeconds)
    }

    /// The ⓘ's text in two paragraphs: what the pass does and when, and
    /// where its frames are held.
    static func explanation() -> String {
        [
            "While you leave Frame Job alone for the time set here, it draws the graphics "
                + "after the playhead in the window you last used, so they play smoothly from the "
                + "start. It stops as soon as you do anything in Frame Job and starts again after "
                + "the same wait, and it keeps the processor busy while it runs.",
            "The frames are held in memory, at most a quarter of this Mac's and less when memory "
                + "is short, until the window closes or newer frames replace them.",
        ].joined(separator: "\n\n")
    }
}
import Foundation

/// Where the person's AssemblyAI key lives, behind a protocol with three
/// verbs — and the two conformers this build ships: a `0600` file, and a
/// value in memory that never touches disk.
///
/// **Why a file and not the Keychain.** The Keychain is the better place and
/// was the plan. Road map 6 §3 q7 MEASURED what an ad-hoc signature does to a
/// login-keychain item: the next build blocks on a `SecurityAgent` modal for
/// a full twenty seconds — even with `kSecUseAuthenticationUIFail`, which
/// does not turn that ACL confirmation into a refusal — and its delete
/// answers `errSecInvalidOwnerEdit`, so the item cannot even be cleaned up by
/// the build that finds it. Every `make app` is a new ad-hoc signature, and
/// an agent-driven instance has nobody to click the modal. The
/// data-protection keychain is not a way out either: `SecItemAdd` there
/// answered `errSecMissingEntitlement` from an unsandboxed ad-hoc-signed app
/// with no keychain access group. **The file is the weaker choice and this
/// paragraph is the record of it**: it is readable by anything running as the
/// person, where a Keychain item is readable by one signed identity after one
/// confirmation. The protocol is what lets a build signed with a stable
/// Developer ID identity add a `KeychainStore` conformer and a one-time
/// migration later without touching anything above it (R6-5, road map 6 §5d).
///
/// **No proof ever reads the person's file.** `MemoryStore` is what a probe
/// gets, and R6-9's `-RCSecretFolder` is what moves a launched app's folder
/// somewhere disposable — `AssemblyAIConfiguration.store` is the one place
/// either is decided.
protocol SecretStore {
    /// The secret, or nil when there is none. Never throws: "no key set" is a
    /// state the sheet names, not an error (road map 6 §5d).
    func read() -> String?
    /// Replaces whatever is there. Throws when it cannot be written, because
    /// a Save button that said nothing and saved nothing is the failure this
    /// is for.
    func write(_ secret: String) throws
    /// Leaves nothing behind. Removing what is not there succeeds.
    func remove() throws
}

/// Why a store could not be written, in a sentence the Settings window can
/// show unchanged.
enum SecretStoreError: LocalizedError, Equatable {
    case unwritable(String)

    var errorDescription: String? {
        switch self {
        case .unwritable(let reason):
            return "The API key could not be saved: \(reason)"
        }
    }
}

/// The shipping conformer: one file, mode `0600`, in a directory created at
/// `0700`.
///
/// **The permissions are on the file from the moment it exists.** It is
/// created with `O_CREAT|O_EXCL` at mode `0600` under a temporary name and
/// `rename(2)`d into place — never written first and `chmod`ed after, which
/// would leave a window in which the key was world-readable, and never
/// through `Data.write`, whose `POSIXPermissions` would be applied to a file
/// that already existed. The rename is also what makes a replacement atomic:
/// a reader sees the old key or the new one, never a half-written file.
///
/// An EXISTING directory's mode is left alone. A person who tightened
/// `~/Library/Application Support/Frame Job/` themselves should keep what they
/// chose, and a directory the app did not create is not the app's to relax.
final class FileStore: SecretStore {

    /// The one spelling of AssemblyAI's file's name, and `name`'s default.
    static let fileName = "assemblyai-key"

    /// The folder the file sits in. `AssemblyAIConfiguration.store` and
    /// `AssistantConfiguration.store` resolve it — from `AppSupport.directory`
    /// for a person, from `-RCSecretFolder` for a proof — and nothing here
    /// reaches for a default of its own, so each key has exactly one line in
    /// the tree that can name a person's real folder (R6-9, AI-13).
    let directory: URL

    /// The file's name in `directory`: `fileName` for AssemblyAI's key,
    /// `AssistantConfiguration.keyFileName` (`anthropic-key`, spec §11 AI-8,
    /// AI-13) for the assistant's. Each store is one file; the temporary a
    /// write renames into place carries the same name.
    let name: String

    var fileURL: URL { directory.appendingPathComponent(name, isDirectory: false) }

    init(directory: URL, name: String = FileStore.fileName) {
        self.directory = directory
        self.name = name
    }

    /// The key, trimmed. An empty or whitespace-only file reads as NO key
    /// rather than as a key that is the empty string: a request with an empty
    /// `authorization` header would be refused by the service with the key
    /// sentence, and "no key is set" is the answer the person can act on.
    func read() -> String? {
        guard let data = try? Data(contentsOf: fileURL),
            let text = String(data: data, encoding: .utf8)
        else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func write(_ secret: String) throws {
        try makeDirectory()
        let temporary = directory.appendingPathComponent(
            ".\(name).\(UUID().uuidString)", isDirectory: false)
        let descriptor = temporary.withUnsafeFileSystemRepresentation { path -> Int32 in
            guard let path = path else { return -1 }
            return open(path, O_WRONLY | O_CREAT | O_EXCL, 0o600)
        }
        guard descriptor >= 0 else {
            throw SecretStoreError.unwritable(String(cString: strerror(errno)))
        }
        if let reason = writeAll(descriptor, Array(secret.utf8)) {
            close(descriptor)
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
        close(descriptor)
        let moved = temporary.withUnsafeFileSystemRepresentation { from -> Int32 in
            guard let from = from else { return -1 }
            return fileURL.withUnsafeFileSystemRepresentation { to -> Int32 in
                guard let to = to else { return -1 }
                return rename(from, to)
            }
        }
        guard moved == 0 else {
            let reason = String(cString: strerror(errno))
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
    }

    func remove() throws {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return }
        do {
            try FileManager.default.removeItem(at: fileURL)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }

    /// The directory through `AppSupport.ensureDirectory` (#108): `mkdir(2)`
    /// at `0700` for each level that is absent, the intermediates included,
    /// and nothing at all for a level that is there. One mode, never
    /// `chmod`ed after.
    private func makeDirectory() throws {
        do {
            try AppSupport.ensureDirectory(directory)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }
}

/// Every byte of `bytes` to `descriptor`, or `strerror`'s sentence. A free
/// function because `write(2)` and `SecretStore.write(_:)` are the same name
/// and a method cannot call the system call without a module qualifier that
/// changes with the SDK.
///
/// **`EINTR` is retried and NOTHING else is.** A signal that landed while the
/// write was in progress is not a failure to write, and turning one into
/// `unwritable` loses a key the person had just typed and told them the disk
/// refused it (the reader review, road map 6 §10.13, H·3). Every other errno
/// is still the sentence it was.
///
/// **The retry is bounded**: at most `writeAllRetryLimit` interruptions per
/// call, and the next one answers `strerror(EINTR)`, so a writer that is
/// interrupted for ever cannot hold the caller for ever (#187, item 6).
///
/// **A write of 0 bytes is its own sentence**, at once and with no retry:
/// `write(2)` sets no `errno` when it answers 0, so `strerror(errno)` would
/// report whatever an earlier call left there (#187, item 6).
///
/// `using` is the probe's seam and nothing else: its default IS `write(2)`,
/// so the shipped path has one spelling, and a row can hand it a writer that
/// answers `EINTR` once before the real one runs.
func writeAll(
    _ descriptor: Int32, _ bytes: [UInt8],
    using write: (Int32, UnsafeRawPointer?, Int) -> Int = { Darwin.write($0, $1, $2) }
) -> String? {
    var offset = 0
    var interruptions = 0
    while offset < bytes.count {
        let written = bytes.withUnsafeBytes { buffer -> Int in
            guard let base = buffer.baseAddress else { return -1 }
            return write(descriptor, base + offset, buffer.count - offset)
        }
        if written > 0 {
            offset += written
            continue
        }
        if written == 0 { return "no bytes were written" }
        if errno == EINTR, interruptions < writeAllRetryLimit {
            interruptions += 1
            continue
        }
        return String(cString: strerror(errno))
    }
    return nil
}

/// How many `EINTR`s one `writeAll` call retries before it answers one.
let writeAllRetryLimit = 100

/// The probe's store, and the empty store R6-9 hands an app that was pointed
/// at a stand-in server. Nothing here touches disk, so no run of any
/// instrument can read or write the person's own key.
final class MemoryStore: SecretStore {
    private let lock = NSLock()
    private var secret: String?

    init(_ secret: String? = nil) {
        self.secret = REDACTED
    }

    func read() -> String? {
        lock.lock()
        defer { lock.unlock() }
        return secret
    }

    func write(_ secret: String) throws {
        lock.lock()
        self.secret = REDACTED
        lock.unlock()
    }

    func remove() throws {
        lock.lock()
        secret = nil
        lock.unlock()
    }
}
import AppKit

/// Settings ▸ Playback ▸ Background render (spec §11 G-38 (a)): a person's
/// setting, like AI-11's model and R6-12's key — no tool reads or writes it
/// and it has no MCP mirror. `PlaybackSettingsPane` is its one writer; a
/// proof sets it in the argument domain and writes nothing.
struct BackgroundRenderSettings: Equatable {
    /// Bool; absent = true.
    static let enabledKey = "FrameJobBackgroundRender"
    /// Int seconds; absent = the default, outside the range clamped into it.
    static let delayKey = "FrameJobBackgroundRenderDelay"
    static let defaultDelay = 5
    static let delayRange = 1...60

    var enabled = true
    var delaySeconds = BackgroundRenderSettings.defaultDelay

    static func load(from defaults: UserDefaults = .standard) -> BackgroundRenderSettings {
        var settings = BackgroundRenderSettings()
        if defaults.object(forKey: enabledKey) != nil {
            settings.enabled = defaults.bool(forKey: enabledKey)
        }
        if defaults.object(forKey: delayKey) != nil {
            let seconds = defaults.integer(forKey: delayKey)
            settings.delaySeconds = min(max(seconds, delayRange.lowerBound), delayRange.upperBound)
        }
        return settings
    }

    /// Writes both keys.
    func save(to defaults: UserDefaults = .standard) {
        defaults.set(enabled, forKey: Self.enabledKey)
        defaults.set(delaySeconds, forKey: Self.delayKey)
    }
}

/// What the idle clock's door answered (`Playback.startBackgroundRender`).
enum BackgroundStart {
    case started
    case notNeeded
    /// Seeking, restoring, rebuilding, holding, or the start refused (a
    /// window plays): the clock runs again.
    case busy
