import AVFoundation
import AppKit

/// The calls a press of Record makes about the four grants, as values a
/// probe can replace: the reads, the four system prompts, the two remembered
/// "asked" flags and the one opener of System Settings. `live` is the app's;
/// `tools/proof/recording_probe.py` puts a sealed spy in
/// `RecorderPanelController.grantDoors` before any mode runs, so no probe
/// can prompt, open Settings or touch the key. Input Monitoring's four
/// (road map creator-jobs CU6, spec §11 CU-62) come last and default INERT —
/// never granted, never asking, never remembering — so a probe that fills
/// only the first ten compiles unchanged and can never prompt.
struct RecorderGrantDoors {
    /// Whether the panel has put up the Screen Recording prompt once
    /// (spec §11 recording). Written only by a launchd-owned press.
    static let screenRecordingAskedKey = "FrameJobScreenRecordingAsked"
    /// Whether the panel has asked for Input Monitoring once (spec §11 CU-3,
    /// CU-62). Written only by a launchd-owned press.
    static let inputMonitoringAskedKey = "FrameJobInputMonitoringAsked"

    var screenGranted: () -> Bool
    var launchedByLaunchd: () -> Bool
    var requestScreen: () -> Void
    var screenAsked: () -> Bool
    var rememberScreenAsked: () -> Void
    var microphoneStatus: () -> AVAuthorizationStatus
    var requestMicrophone: (@escaping () -> Void) -> Void
    var openSettings: (URL) -> Bool
    /// The Camera grant (CR1c, spec §11 CAM-5), asked only for Source Camera.
    var cameraStatus: () -> AVAuthorizationStatus
    var requestCamera: (@escaping () -> Void) -> Void
    /// Input Monitoring (CU-62), read only with Record shortcuts on.
    var inputMonitoringGranted: () -> Bool = { false }
    var requestInputMonitoring: () -> Void = {}
    var inputMonitoringAsked: () -> Bool = { false }
    var rememberInputMonitoringAsked: () -> Void = {}

    static var live: RecorderGrantDoors {
        RecorderGrantDoors(
            screenGranted: { RecordingGrant.screenRecordingGranted },
            launchedByLaunchd: { RecordingGrant.launchedByLaunchd },
            requestScreen: { _ = CGRequestScreenCaptureAccess() },
            screenAsked: { UserDefaults.standard.bool(forKey: screenRecordingAskedKey) },
            rememberScreenAsked: { UserDefaults.standard.set(true, forKey: screenRecordingAskedKey) },
            microphoneStatus: { RecordingGrant.microphoneStatus },
            requestMicrophone: { answered in
                // The framework does not say which queue it answers on, so
                // the answer hops to main.
                AVCaptureDevice.requestAccess(for: .audio) { _ in
                    DispatchQueue.main.async { answered() }
                }
            },
            openSettings: { url in NSWorkspace.shared.open(url) },
            cameraStatus: { RecordingGrant.cameraStatus },
            requestCamera: { answered in
                // As the microphone's: the answer hops to main.
                AVCaptureDevice.requestAccess(for: .video) { _ in
                    DispatchQueue.main.async { answered() }
                }
            },
            inputMonitoringGranted: { RecordingGrant.inputMonitoringGranted },
            requestInputMonitoring: { _ = CGRequestListenEventAccess() },
            inputMonitoringAsked: { UserDefaults.standard.bool(forKey: inputMonitoringAskedKey) },
            rememberInputMonitoringAsked: {
                UserDefaults.standard.set(true, forKey: inputMonitoringAskedKey)
            })
    }
}

/// The grants, for the recorder panel (road map 3, R1c; spec §11
/// recording) — `RecorderPanelController.swift`'s seventh file, cut out of
/// `+Recording.swift` when the press learned to open System Settings.
///
/// **The grants are asked for HERE and nowhere else, and UNCONDITIONALLY**
/// (decision 4: the TOOL never asks — it reads the status and refuses by

    /// number out of either state, so the file that gets written is
    /// identical, and one number cannot disagree with itself the way a row
    /// plus a value can.
    var loudness: Double?

    /// True for "In/out range". Degrades to "Whole project" on a document
    /// that has no range — the popup only carries that row when it does.
    var inOutRange: Bool = false

    /// The burn-in checkbox. It is a RECIPE option rather than an export
    /// override (`RecipeOptions`), but from this sheet's side it is one more
    /// control, and a preset that remembered every choice but that one would
    /// be a preset that quietly stopped burning in.
    var burnInTimecode: Bool = false

    /// The Speed popup's last word (`EncoderSpeed`, spec §11 CX-12 (2)), stored on every
    /// row so the popup keeps it across formats; only `av1` sends it.
    var encoderSpeed: String?

    /// The Bit depth popup's last choice (16 or 24, spec §11 AU-29), stored on every row so
    /// the popup keeps it across formats; only `audio_wav` and `audio_aiff` send it.
    var audioBits: Int?

    /// The Stems popup's last word ("tracks" or "names", nil for None, spec §11 AU-108),
    /// stored on every row so the popup keeps it across formats; only the audio rows send it.
    var stems: String?

    /// The file's spelling. Snake case because a person can open
    /// `ExportPresets.json` in an editor, and because `burn_in_timecode` is
    /// then the same string the core's recipe options use — one name for one
    /// idea, even across the FFI it never crosses.
    private enum CodingKeys: String, CodingKey {
        case name
        case presetID = "preset_id"
        case sizeRow = "size_row"
        case customSize = "custom_size"
        case fps
        case qualityTier = "quality_tier"
        case loudness
        case inOutRange = "in_out_range"
        case burnInTimecode = "burn_in_timecode"
        case encoderSpeed = "encoder_speed"
        case audioBits = "audio_bits"
        case stems
    }

    init(
        name: String = "", presetID: String = "", sizeRow: String? = nil,
        customSize: [Int]? = nil, fps: [Int]? = nil, qualityTier: String? = nil,
        loudness: Double? = nil, inOutRange: Bool = false, burnInTimecode: Bool = false,
        encoderSpeed: String? = nil, audioBits: Int? = nil, stems: String? = nil
    ) {
        self.name = name
        self.presetID = presetID
        self.sizeRow = sizeRow
        self.customSize = customSize
        self.fps = fps
        self.qualityTier = qualityTier
        self.loudness = loudness
        self.inOutRange = inOutRange
        self.burnInTimecode = burnInTimecode
        self.encoderSpeed = encoderSpeed
        self.audioBits = audioBits
        self.stems = stems
    }

    /// Every key optional, every absence a default.
    ///
    /// Written by hand rather than synthesized because the synthesized
    /// decoder THROWS on a missing non-optional, and this record is read from
    /// a file a person can edit and from a defaults value an older build
    /// wrote. One missing `burn_in_timecode` would otherwise fail the whole
    /// array's decode and take every other preset down with it — the shape of
    /// failure `load()` promises never to have.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        name = (try? c.decodeIfPresent(String.self, forKey: .name)) ?? ""
        presetID = (try? c.decodeIfPresent(String.self, forKey: .presetID)) ?? ""
        sizeRow = try? c.decodeIfPresent(String.self, forKey: .sizeRow)
        customSize = try? c.decodeIfPresent([Int].self, forKey: .customSize)
        fps = try? c.decodeIfPresent([Int].self, forKey: .fps)
        qualityTier = try? c.decodeIfPresent(String.self, forKey: .qualityTier)
        loudness = try? c.decodeIfPresent(Double.self, forKey: .loudness)
        inOutRange = (try? c.decodeIfPresent(Bool.self, forKey: .inOutRange)) ?? false
        burnInTimecode = (try? c.decodeIfPresent(Bool.self, forKey: .burnInTimecode)) ?? false
        encoderSpeed = try? c.decodeIfPresent(String.self, forKey: .encoderSpeed)
        audioBits = try? c.decodeIfPresent(Int.self, forKey: .audioBits)
        stems = try? c.decodeIfPresent(String.self, forKey: .stems)
    }
}

